		assert.ErrorContains(t, err, "connection closed unexpectedly by the other side: EOF")
	})
	t.Run("timeout", func(t *testing.T) {
		t.Parallel()

		timeout := 10 * time.Millisecond

		addr := bootstrapConnections(t, 1, func(nc net.Conn) {
